mapper.select:
SELECT a.BALANCE_DATE as balanceDate, '' as finprodId, bokset.BOOKSET_ID AS booksetId, bokset.BOOKSET_NAME as booksetName, a.SUBJECT_NO AS subjectNo, IFNULL(subject.SUBJECT_NAME,bbd.DETAIL_SUBJECT_NAME) AS subjectName, a.O_CCY AS oCcy, sum(a.O_AMT) AS oAmt, a.B_CCY AS bCCy, sum(a.B_AMT) AS bAmt, a.BAL_FLAG AS balFlag, sum(a.NUM_AMT) AS numAmt FROM BOK_BANK_POSITION a LEFT JOIN BOK_BOOKSET bokset ON a.BOOKSET_ID = bokset.BOOKSET_ID LEFT JOIN BOK_SUBJECT subject ON a.SUBJECT_NO = subject.SUBJECT_NO AND bokset.BOOKSET_ID_TMPL = subject.BOOKSET_ID LEFT JOIN BOK_BUSS_DETSUB bbd ON bbd.BOOKSET_ID = a.BOOKSET_ID AND bbd.DETAIL_SUBJECT_NO = a.SUBJECT_NO WHERE 1=1 AND bokset.ACCT_SUBJECT_TYPE ='BANK'
AND a.FINPROD_ID IN
#{finprodId}
AND a.SUBJECT_NO = #{subjectNo}
AND a.BALANCE_DATE >=STR_TO_DATE(#{bookDateBegin},'yyyy-MM-dd')
AND a.BALANCE_DATE <=STR_TO_DATE(#{bookDateEnd},'yyyy-MM-dd')
AND a.O_CCY IN
#{ccy}
GROUP BY a.BALANCE_DATE, bokset.BOOKSET_ID, bokset.BOOKSET_NAME, a.SUBJECT_NO, IFNULL(subject.SUBJECT_NAME,bbd.DETAIL_SUBJECT_NAME), a.O_CCY, a.B_CCY, a.BAL_FLAG ORDER BY a.BALANCE_DATE desc, a.SUBJECT_NO asc
